    ('2026-10-13T00:59:50.049Z · Rework confirmation baseline per third review',
     'from pathlib import Path\np = Path(JSX); t = p.read_text(encoding="utf-8")\ndef rep(a, b):\n    global t\n    assert t.count(a) == 1, (t.count(a), a[:100]); t = t.replace(a, b)\n\n# ── safetyReview: objetivo máximo solo de tramos infundidos; helper de texto ──\nrep(\'\'\'  const maxTarget = Math.max(...plan.target);\n  if (maxTarget > SAFETY.targetCp.soft) {\n    add("soft", "target", maxTarget, `Cp objetivo ${fmt(maxTarget, 2)} ng/mL > ${SAFETY.targetCp.soft} ng/mL (equilibrio ≈ ${fmt(maxTarget * clearanceKgH(plan.pk.model, maxTarget), 1)} µg/kg/h, por encima de las CRI habituales).`);\n  }\'\'\',\n\'\'\'  // Objetivo máximo de los tramos que llegan a infundirse: un objetivo fijado en pausa y sustituido antes de reanudar no cuenta\n  const maxTarget = Math.max(...plan.steps.filter(x => x.kind !== "pause").map(x => x.targetCp));\n  if (maxTarget > SAFETY.targetCp.soft) add("soft", "target", maxTarget, targetWarning(plan.pk.model, maxTarget));\'\'\')\nrep(\'\'\'/** Texto de la acción que exige un paso del programa. */\'\'\',\n\'\'\'/** Aviso blando de Cp objetivo alta (se usa también al fijar un objetivo durante una pausa). */\nfunction targetWarning(model, cp) {\n  return `Cp objetivo ${fmt(cp, 2)} ng/mL > ${SAFETY.targetCp.soft} ng/mL (equilibrio ≈ ${fmt(cp * clearanceKgH(model, cp), 1)} µg/kg/h, por encima de las CRI habituales).`;\n}\n\n/** Texto de la acción que exige un paso del programa. */\'\'\')\n\n# ── newOrWorse sobre listas de items, con margen por código y sin confundir niveles ──\ns0 = t.index("/**\\n * Avisos de `candidate` (nivel `level`) nuevos respecto a `current`")\ns1 = t.index("/** Aviso blando de Cp objetivo alta")\nt = t[:s0] + \'\'\'/** Margen para considerar «peor» un aviso ya confirmado: el objetivo, cualquier subida; el resto, más de un 2 %. */\nconst worseMargin = code => (code === "target" ? 0 : 0.02);\n\n/**\n * Avisos de `candidateItems` (nivel `level`) nuevos respecto a `confirmedItems` o con un valor mayor que el ya\n * confirmado (más allá de worseMargin). Un aviso que baja o se mantiene no se vuelve a pedir. Para los blandos\n * cuenta también un límite duro ya confirmado del mismo código (bajar desde un límite duro no pide nada).\n */\nfunction newOrWorse(candidateItems, confirmedItems, level) {\n  const confirmed = new Map();\n  for (const i of confirmedItems) {\n    if (i.level === level || (level === "soft" && i.level === "hard")) confirmed.set(i.code, Math.max(confirmed.get(i.code) ?? -Infinity, i.value));\n  }\n  const worst = new Map();\n  for (const i of candidateItems) {\n    if (i.level !== level) continue;\n    if (confirmed.has(i.code) && i.value <= confirmed.get(i.code) * (1 + worseMargin(i.code)) + 1e-9) continue;\n    if (!worst.has(i.code) || i.value > worst.get(i.code).value) worst.set(i.code, i);\n  }\n  return [...worst.values()];\n}\n\n/** ¿Una confirmación guardada (Map código → valor mostrado) cubre estos avisos sin que hayan empeorado? */\nconst confirmationCovers = (stored, items) => !!stored\n  && items.every(i => stored.has(i.code) && (i.value ?? 0) <= (stored.get(i.code) ?? 0) * (1 + worseMargin(i.code)) + 1e-9);\nconst asConfirmation = items => new Map(items.map(i => [i.code, i.value ?? 0]));\n\n\'\'\' + t[s1:]\n\n# ── estado ──\nrep(\'\'\'  const [targetConfirm, setTargetConfirm] = useState(null); // cambio de objetivo pendiente: { value, paused, codes }\n  const [resumeConfirm, setResumeConfirm] = useState(null); // avisos nuevos al reanudar pendientes: Set de códigos\'\'\',\n\'\'\'  const [targetConfirm, setTargetConfirm] = useState(null); // cambio de objetivo pendiente: { value, paused, shown: Map }\n  const [resumeConfirm, setResumeConfirm] = useState(null); // avisos al reanudar mostrados: Map código → valor\n  const [pauseBaseline, setPauseBaseline] = useState(null); // avisos confirmados al pausar (+ los confirmados en pausa)\'\'\')\nrep(\'\'\'    setTargetConfirm(null);\n    setResumeConfirm(null);\n    setEndSec(null);\'\'\',\n\'\'\'    setTargetConfirm(null);\n    setResumeConfirm(null);\n    setPauseBaseline(null);\n    setEndSec(null);\'\'\')\n\n# ── pauseRun: guardar lo confirmado ──\nrep(\'\'\'    setTargetConfirm(null);\n    setResumeConfirm(null);\n    setTargetError(null);\n    setStatus("paused");\'\'\',\n\'\'\'    setTargetConfirm(null);\n    setResumeConfirm(null);\n    setPauseBaseline(review.items);                // lo confirmado hasta ahora: línea base al reanudar\n    setTargetError(null);\n    setStatus("paused");\'\'\')\n\n# ── resumeRun ──\nr0 = t.index("    const targetCp = plan.target[sec];             // incluye un objetivo fijado en pausa en este mismo segundo\\n    const changes = [...targetChanges.filter(c => c.sec < sec), { sec, targetCp }];\\n    // Inicio de la pausa en curso")\nr1 = t.index("    setStatus(\\"running\\");\\n    setTargetChanges(changes);")\nt = t[:r0] + \'\'\'    const targetCp = plan.target[sec];             // incluye un objetivo fijado en pausa en este mismo segundo\n    const changes = [...targetChanges.filter(c => c.sec < sec), { sec, targetCp }];\n    // Límites con la recarga real (hora de reanudación) frente a lo confirmado al pausar y durante la pausa:\n    // un límite duro nuevo o peor impide reanudar; los blandos nuevos o peores se confirman con un segundo clic\n    const baseline = pauseBaseline ?? review.items;\n    const candidate = safetyReview(buildPlan(config, changes, timing), config);\n    const hardNew = newOrWorse(candidate.items, baseline, "hard");\n    if (hardNew.length) {\n      setResumeConfirm(null);\n      setTargetError(`Límite duro al reanudar: ${hardNew.map(i => i.text).join(" ")} Espere o baje el objetivo.`);\n      return;\n    }\n    const softNew = newOrWorse(candidate.items, baseline, "soft");\n    if (softNew.length && !confirmationCovers(resumeConfirm, softNew)) {\n      setResumeConfirm(asConfirmation(softNew));\n      setTargetError(`Aviso al reanudar: ${softNew.map(i => i.text).join(" ")} Pulse «Reanudar» de nuevo para confirmar.`);\n      return;\n    }\n    // Inicio de la pausa en curso: el primero de los últimos tramos en pausa (cambiar el objetivo en pausa añade otro)\n    const pauseStart = targetChanges.reduce((start, c) => (c.pause ? start ?? c.sec : null), null) ?? sec;\n\'\'\' + t[r1:]\nrep(\'\'\'    setStatus("running");\n    setTargetChanges(changes);\n    setResumeConfirm(null);\n    setTargetError(null);\'\'\',\n\'\'\'    setStatus("running");\n    setTargetChanges(changes);\n    setResumeConfirm(null);\n    setPauseBaseline(null);\n    setTargetError(null);\'\'\')\n\n# ── applyTargetChange ──\na0 = t.index("    // Límites frente a lo ya confirmado (newOrWorse): solo se avisa de lo nuevo o peor; bajar no pide nada.")\na1 = t.index("    // En pausa la bomba sigue parada: el nuevo objetivo se aplica al reanudar")\nt = t[:a0] + \'\'\'    // Límites frente a lo ya confirmado (newOrWorse): solo se avisa de lo nuevo o peor; bajar no pide nada.\n    // En pausa el objetivo se aplica al reanudar: el límite duro y los avisos de la recarga se revisan entonces\n    // (resumeRun), con la hora real; aquí solo se confirma el aviso del propio objetivo.\n    const kept = targetChanges.filter(c => c.sec < sec);\n    let newSoft;\n    if (paused) {\n      const item = { level: "soft", code: "target", value: parsed.value, text: targetWarning(config.model, parsed.value) };\n      newSoft = parsed.value > SAFETY.targetCp.soft ? newOrWorse([item], pauseBaseline ?? review.items, "soft") : [];\n    } else {\n      const candidatePlan = buildPlan(config, [...kept, { sec, targetCp: parsed.value }], timing);\n      const candidate = safetyReview(candidatePlan, config);\n      const hardNew = newOrWorse(candidate.items, review.items, "hard");\n      if (hardNew.length) { setTargetError(`Límite duro: ${hardNew.map(i => i.text).join(" ")}`); return; }\n      newSoft = newOrWorse(candidate.items, review.items, "soft");\n      // Subir durante una carga: la carga en curso se sustituye por otra calculada desde la Cp actual.\n      // Cuenta lo que infunde la bomba (en modo manual, el último paso confirmado) y lo que pide el plan nuevo\n      const pumpStep = plan.steps[autoPump ? activeIdx : ackIdx];\n      const loading = pumpStep.kind === "load" && (!autoPump || elapsedSec < pumpStep.sec + pumpStep.loadSec);\n      if (parsed.value > previous && loading && candidatePlan.steps.find(s => s.sec === sec)?.kind === "load") {\n        newSoft.unshift({ code: "reload", text: `Subida durante la carga en curso: se sustituye por una nueva carga hasta ${fmt(parsed.value, 2)} ng/mL.` });\n      }\n    }\n    if (parsed.value - previous > SAFETY.targetStep.soft + 1e-9) {\n      newSoft.unshift({ code: "step", text: `Subida de ${fmt(parsed.value - previous, 2)} ng/mL > ${SAFETY.targetStep.soft} ng/mL por cambio.` });\n    }\n    const confirmed = targetConfirm && targetConfirm.value === parsed.value && targetConfirm.paused === paused\n      && confirmationCovers(targetConfirm.shown, newSoft);\n    if (newSoft.length && !confirmed) {\n      setTargetConfirm({ value: parsed.value, paused, shown: asConfirmation(newSoft) });\n      setTargetError(`Aviso: ${newSoft.map(i => i.text).join(" ")} Pulse «Aplicar» de nuevo para confirmar.`);\n      return;\n    }\n    // Lo confirmado en pausa pasa a la línea base de la reanudación (no se vuelve a pedir al reanudar)\n    if (paused) setPauseBaseline(prev => [...(prev ?? review.items), ...newSoft.filter(i => i.level)]);\n\'\'\' + t[a1:]\np.write_text(t, encoding="utf-8"); print("ok")\n'),
